---@class ActivityMidFestivalBossHomeDojo
local ActivityMidFestivalBossHomeDojo = Class("ActivityMidFestivalBossHomeDojo")

function ActivityMidFestivalBossHomeDojo:__init()
    self.playerRank = {
        ranking = 0,            --- 名次
        score = 0               --- 伤害
    }        --- 我的排名
    self.hurtDrawRewardId = 0   --- 领取的伤害奖励id
    self.historyMaxHurt = 0     --- 历史最高的伤害
    self.percentageRank = 0     --- 百分比排名
    self.rankInfo = {}          --- key 排行榜名次 value list
end

function ActivityMidFestivalBossHomeDojo:__delete()
    self.playerRank = nil
    self.hurtDrawRewardId = nil
    self.historyMaxHurt = nil
    self.percentageRank = nil
    self.rankInfo = nil
end

---Update
---更新数据
---@param jsonData table
function ActivityMidFestivalBossHomeDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
        end
    end
end

function ActivityMidFestivalBossHomeDojo:DrawReward(rewardId)
    -- rewardId为空表示一键领取
    if isNull(rewardId) then
        -- 1. 获取所有奖励
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
        local allRewards = comp:GetRankRewards()
        -- 2. 获取所有可领取但未领取的奖励
        local allCanDrawButNotInListRewards = {}
        for i, reward in ipairs(allRewards) do
            ---@type MidFestivalBossDamageRewardVo
            local rewardVo = reward
            if checkNumber(self.historyMaxHurt) >= checkNumber(rewardVo.upperLimit) and (not self:IsRewardDraw(rewardVo.id)) then
                table.insert(allCanDrawButNotInListRewards, rewardVo)
            end
        end
        -- 3. 将他们全部设置为已领取
        for _, rewardVo in ipairs(allCanDrawButNotInListRewards) do
            self.hurtDrawRewardId[checkString(rewardVo.id)] = 1
        end
        return
    end

    if not self:IsRewardDraw(rewardId) then
        self.hurtDrawRewardId[checkString(rewardId)] = 1
    end
end

function ActivityMidFestivalBossHomeDojo:IsRewardDraw(rewardId)
    return self.hurtDrawRewardId[checkString(rewardId)] == 1
end

return ActivityMidFestivalBossHomeDojo